void ValidateVersion(std::string_view text,bool allowSunshineMarker){
 if(text.empty()||text.size()>44)throw std::runtime_error("Invalid bounded GameStream version.");size_t at=0;
 for(unsigned component=0;component<4;++component){const auto end=text.find('.',at);if((component<3&&end==text.npos)||(component==3&&end!=text.npos))throw std::runtime_error("GameStream versions require exactly four components.");const auto value=text.substr(at,end==text.npos?text.size()-at:end-at);if(!(component==3&&allowSunshineMarker&&value=="-1"))(void)Decimal(value,0x7fffffff);if(end!=text.npos)at=end+1;}
}
